def _clean_value(v, clip_max=99.0):
    if v is None:
        v = 0.0
    else:
        v = float(v)
        if math.isnan(v):
            v = 0.0
        elif math.isinf(v):
            v = clip_max if v > 0 else 0.0

    if not np.isfinite(v):
        v = 0.0

    return max(0.0, min(float(v), clip_max))


